  document.querySelectorAll('.objective')[1].classList.toggle('done',state.photo);
  $('missionProgress').style.width=`${(Number(state.probe)+Number(state.photo))*50}%`;
  $('probeAction').classList.toggle('active',state.probe);$('photoAction').classList.toggle('active',state.photo);
  $('warningPill').querySelector('small').textContent=`EF${state.ef} · trajectoire NE · ${Math.round(dist)} m`;
  if(state.probe&&state.photo&&!state.completed)completeMission();
}
function update(dt){
  if(state.paused)return;
  state.time+=dt;state.dayTime=(state.dayTime+dt*.005)%24;
  const accelerating=keys.has('w')||keys.has('arrowup'),braking=keys.has('s')||keys.has('arrowdown');
  const steering=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0);
  const maxSpeed=vehicles[state.vehicle].speed*(state.damage<35?.68:1);
  if(accelerating){state.speed+=52*dt;state.gear='D'}else if(braking){state.speed-=75*dt;state.gear=state.speed<1?'R':'D'}else state.speed-=12*dt;
  state.speed=clamp(state.speed,0,maxSpeed);
  state.x+=steering*dt*(35+state.speed*.38);state.x=clamp(state.x,-205,205);
  if(state.speed>5)state.traveled+=state.speed*dt*.22;
  state.stormZ-=dt*(1.7+state.speed*.27);state.stormX+=Math.sin(state.time*.12)*dt*2.7;
  if(state.stormZ<260&&Math.random()<dt*.018)state.stormX+=rand(-22,22);
  if(state.stormZ<85&&!state.completed){state.ef=Math.min(5,state.ef);state.stormZ=85;state.shake=Math.max(state.shake,1.8)}
  state.stormPhase+=dt*(1.15+state.ef*.17);
  state.fuel=Math.max(0,state.fuel-dt*(.018+state.speed*.00015));
  state.rain=.42+.24*Math.sin(state.time*.045)+.12*Math.sin(state.time*.17);
  if(state.speed>30&&state.x>130&&state.x<190&&Math.random()<dt*.12){state.damage=Math.max(10,state.damage-5);state.x-=10;showToast('⚠ Sortie de route : dégâts au véhicule');state.shake=5}
  if(state.stormZ<520){state.shake=Math.max(state.shake,Math.min(1.3,(520-state.stormZ)/500))}
  if(state.shake>0)state.shake=Math.max(0,state.shake-dt*3);
  if(state.flash>0)state.flash=Math.max(0,state.flash-dt*1.6);
  if(Math.random()<dt*.008)state.flash=.85;
  if(state.toastTimer>0){state.toastTimer-=dt;if(state.toastTimer<=0)$('toast').classList.remove('show')}
  if(state.photoCooldown>0)state.photoCooldown-=dt;if(state.probeCooldown>0)state.probeCooldown-=dt;
  updateHud();
}
let frame=0;
function loop(now){
  const dt=Math.min(.04,(now-state.last)/1000||0);state.last=now;
  update(dt);drawScene();
  if(++frame%3===0){drawRadar();drawMap()}
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

