  addEventListener('resize', resize); resize();
  function makeObjects(){
    state.objects=[];
    for(let i=0;i<38;i++){
      const side=i%2?1:-1;
      state.objects.push({z:rand(100,3000),x:side*rand(95,240),kind:Math.random()<.67?'tree':'building',seed:rand(0,100)});
