11:       if (!await control.isVisible() || !await control.isEnabled()) continue
12:       const eligible = await control.evaluate((element, explicit) => {
13:         if (element.closest('a[href], form') || element.getAttribute('aria-disabled') === 'true') return false
14:         if (explicit) return true
15:         const label = element.getAttribute('aria-label') || element.value || element.textContent || ''
16:         return /^(?:start|play)(?:\s+(?:game|now))?$/i.test(label.trim())
